function validate([matrix, k]) {
  if (!Array.isArray(matrix) || matrix.length < 1 || matrix.length > 1000) return 'matrix needs 1 to 1000 rows.';
  const n = Array.isArray(matrix[0]) ? matrix[0].length : 0;
  if (n < 1 || n > 1000) return 'Each row needs 1 to 1000 values.';
  for (const row of matrix) {
    if (!Array.isArray(row) || row.length !== n) return 'All rows must have the same length.';
    if (row.some(v => !Number.isInteger(v) || v < 0 || v > 1000000)) return 'Each value is an integer from 0 to 10^6.';
  }
  if (!Number.isInteger(k) || k < 1 || k > matrix.length * n) return 'k is between 1 and m * n.';
  return null;
}

