function kthLargestValue(matrix, k) {
  const all = [];
  for (let a = 0; a < matrix.length; a++) {
    for (let b = 0; b < matrix[0].length; b++) {
      let value = 0;
      for (let i = 0; i <= a; i++) for (let j = 0; j <= b; j++) value ^= matrix[i][j];
      all.push(value);
    }
  }
  all.sort((p, q) => p - q);
  return all[all.length - k];
}

