function generate(rand, size) {
  const large = size === 'large';
  const m = large ? 100 : 1 + Math.floor(rand() * 4);
  const n = large ? 100 : 1 + Math.floor(rand() * 4);
  const top = large || rand() < 0.3 ? 1000000 : rand() < 0.5 ? 3 : 15;
  const matrix = Array.from({ length: m }, () => Array.from({ length: n }, () => Math.floor(rand() * (top + 1))));
  const k = 1 + Math.floor(rand() * m * n);
  return [matrix, k];
}
